package postgres
import("context";"os";"testing";"github.com/jackc/pgx/v5/pgxpool";"github.com/google/uuid";"github.com/menerjangbadai/dashboard/db";"github.com/menerjangbadai/dashboard/internal/application";"github.com/menerjangbadai/dashboard/internal/domain")
func testStore(t *testing.T)*Store{t.Helper();u:=os.Getenv("MB_TEST_DATABASE_URL");if u==""{if os.Getenv("MB_INTEGRATION")=="1"{t.Fatal("MB_INTEGRATION=1 requires MB_TEST_DATABASE_URL")};t.Skip("set MB_TEST_DATABASE_URL for real PostgreSQL integration")};ctx:=context.Background();p,e:=pgxpool.New(ctx,u);if e!=nil{t.Fatal("database config invalid")};t.Cleanup(p.Close);if e=p.Ping(ctx);e!=nil{t.Fatal("requested integration database unavailable")};if e=db.Migrate(ctx,p);e!=nil{t.Fatal(e)};return &Store{Pool:p}}
func TestRealBrandIsolationAndArchive(t *testing.T){s:=testStore(t);ctx:=context.Background();a,e:=s.Bootstrap(ctx,"https://issuer.test/",uuid.NewString(),"Owner");if e!=nil{t.Fatal(e)};uc:=application.Brands{Repo:s};b,e:=uc.Create(ctx,a,domain.Brand{Name:"Real brand",Website:"https://example.org"});if e!=nil{t.Fatal(e)};other,e:=s.Bootstrap(ctx,"https://issuer.test/",uuid.NewString(),"Other");if e!=nil{t.Fatal(e)};if _,e=uc.Get(ctx,other,b.ID);e!=domain.ErrNotFound{t.Fatalf("cross org: %v",e)};items,e:=uc.List(ctx,a);if e!=nil||len(items)!=1{t.Fatal(items,e)};b.Status="archived";if _,e=uc.Update(ctx,a,b);e!=nil{t.Fatal(e)};b,e=uc.Get(ctx,a,b.ID);if e!=nil||b.Status!="archived"{t.Fatal(b,e)}
 // Same org, no explicit brand grant: owner is not an ACL bypass.
 _,e=s.Pool.Exec(ctx,"INSERT INTO organization_members(org_id,user_id) VALUES($1,$2)",a.OrgID,other.UserID);if e!=nil{t.Fatal(e)};_,e=s.Pool.Exec(ctx,"INSERT INTO user_roles(org_id,user_id,role_id) VALUES($1,$2,'owner')",a.OrgID,other.UserID);if e!=nil{t.Fatal(e)};other.OrgID=a.OrgID;if _,e=uc.Get(ctx,other,b.ID);e!=domain.ErrNotFound{t.Fatal("missing grant bypass",e)}
}
